<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('Administrator');$pageTitle='Add User';$activeMenu='users';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim($_POST['username']);$first=trim($_POST['first_name']);$last=trim($_POST['last_name']);$email=trim($_POST['email']);$password=$_POST['password'];$role=(int)$_POST['role_id'];$dept=(int)($_POST['department_id']??0)?:null;if(!preg_match('/^[A-Za-z0-9._-]{3,50}$/',$username))$errors[]='Username must be 3–50 characters using letters, numbers, dot, dash or underscore.';if($first===''||$last==='')$errors[]='First and last name are required.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';if(!$role)$errors[]='Role is required.';if(!$errors){try{$s=db()->prepare('INSERT INTO users(username,password_hash,first_name,last_name,email,role_id,department_id,is_active) VALUES(?,?,?,?,?,?,?,1)');$s->execute([$username,password_hash($password,PASSWORD_DEFAULT),$first,$last,$email,$role,$dept]);log_activity('CREATE','Users','Created user '.$username);flash('success','User account created.');redirect('users/index.php');}catch(PDOException $e){$errors[]='Username or email already exists.';}}}$roles=db()->query('SELECT id,name FROM roles ORDER BY id')->fetchAll();$departments=departments();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Add User</h1><p>Create a secure user account and assign role-based access.</p></div><a class="btn btn-light border" href="<?=e(url('users/index.php'))?>">Back</a></div><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><div class="card-panel"><div class="card-body"><form method="post" autocomplete="off"><?=csrf_field()?><div class="row g-3"><div class="col-md-4"><label class="form-label">Username</label><input class="form-control" name="username" value="<?=e($_POST['username']??'')?>" required></div><div class="col-md-4"><label class="form-label">First Name</label><input class="form-control" name="first_name" value="<?=e($_POST['first_name']??'')?>" required></div><div class="col-md-4"><label class="form-label">Last Name</label><input class="form-control" name="last_name" value="<?=e($_POST['last_name']??'')?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email" value="<?=e($_POST['email']??'')?>" required></div><div class="col-md-6"><label class="form-label">Initial Password</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="col-md-6"><label class="form-label">Role</label><select class="form-select" name="role_id"><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Department</label><select class="form-select" name="department_id"><option value="">No department</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-primary px-4">Create User</button></div></div></form></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
